  function borgoArea() { const tx = Math.floor(B.x / TS), ty = Math.floor((B.y - 4) / TS); const a = AREAS.find(([x0, y0, x1, y1]) => tx >= x0 && tx <= x1 && ty >= y0 && ty <= y1); return a ? a[4] : "Borgo Marino"; }
  function borgoHint() {
    if (view.kind !== "borgo") return;
    const hints = { Porto: "Il muro del porto, il molo di Baciccia e la trattoria di papà.", Spiaggia: "Sabbia, ombrelloni e qualche conchiglia nascosta.", Campo: "Il campetto dove è cominciato tutto. L'erba cresce solo ai lati. La Casa delle Stelle è in fondo, oltre il lato est del campo.", "Casa delle Stelle": `La sede delle reclute del Borgo. ${hqCount()}/108 persone conosciute: avvicinati alla porta e premi Parla per entrare.`, Piazza: "La chiesa di San Pietro, la fontana, l'edicola della signora Pina.", "Casa Ferri": "La casa della Nonna Ferri. Un arancio, una Panda del 1994.", "Il nascondiglio": "Un posto che nessuno conosce. O quasi.", "Borgo Marino": "Le strade del paese. Il pullman per Genova ferma a est.", Collina: "La collina delle capre. In cima c'è una panchina che guarda il mare.", "Strada della costa": "La strada che porta fuori dal paese. E, a quanto pare, anche dentro.", "Vecchio stadio": "Il vecchio stadio del Borgo. Tribune di legno, erba tagliata con le forbici.", Faro: "Il faro di Punta Rondine. Di notte, forse, si accende.", "Molo lungo": "Il molo nuovo. Di notte, in fondo, qualcuno pesca con la lampara." };
    const info = BW.showInfo && BW.info ? `<br><span style="color:var(--dim)">${esc(BW.info.head)}.</span>` : "";
    if (BW.showInfo && BW.infoArea && BW.infoArea !== BW.area) BW.showInfo = false; else BW.infoArea = BW.area;
    text("voce", `<b>${esc(BW.area)}</b> · ${esc(hints[BW.area] || "")} <span style="color:var(--dim)">Frecce per muoverti, <em>Parla</em> vicino a qualcuno. I punti <em>!</em> hanno qualcosa da chiederti.</span>${info}`);
  }
  function borgoTry(nx, ny) {
    nx = clamp(nx, 6, MW * TS - 6); ny = clamp(ny, 8, MH * TS - 2);
    for (const [ox, oy] of [[-5, -4], [5, -4], [-5, 2], [5, 2]]) if (SOLID.includes(tileAt(nx + ox, ny + oy))) return false;
    for (const n of npcList()) if (Math.abs(nx - n.x) < 11 && Math.abs(ny - n.y) < 8) return false;
    B.x = nx; B.y = ny; return true;
  }
  const DIRV = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] };
  function borgoTarget() {
    const [vx, vy] = DIRV[B.dir] || [0, 1];
    const fx = B.x + vx * 13, fy = B.y - 2 + vy * 13;
    const npcs = npcList();
    let t = npcs.find((n) => Math.hypot(n.x - fx, n.y - fy) < 13);
    let target = t ? { kind: "npc", id: t.id, label: "Parla" } : null;
    if (!target) { try { target = bsTarget(fx, fy); } catch { target = null; } }
    if (!target) { t = npcs.find((n) => Math.hypot(n.x - B.x, n.y - B.y) < 19); target = t ? { kind: "npc", id: t.id, label: "Parla" } : null; }
    if (!target) {
      const tx = Math.floor(fx / TS), ty = Math.floor(fy / TS), ch = BW.map[ty] && BW.map[ty][tx];
      if (ch && "DWSXOKVJQ".includes(ch)) target = { kind: "obj", ch, tx, ty, label: { D: "Entra", W: "Tira al muro", S: "Aspetta il bus", X: "Apri", O: "Guarda", K: "Guarda", V: "Siediti", J: "Guarda", Q: "Bacheca Incarichi" }[ch], id: ch + tx + "," + ty };
    }
    BW.target = target;
    const key = target ? target.id + target.label : "";
    if (key !== BW.tkey) { BW.tkey = key; const b = $("bAct"); if (b) { b.textContent = target ? target.label : "Parla"; b.disabled = !target; } }
  }
  function borgoToast(t) { if (BW) BW.toast = { text: t, t: 200 }; }
  function borgoPickups() {
    const tx = Math.floor(B.x / TS), ty = Math.floor((B.y - 4) / TS);
    SHELLS.forEach(([sx, sy, when], i) => {
      if (sx !== tx || sy !== ty || B.shells.includes(i) || (when === "notte" && !B.night)) return;
      B.shells.push(i); borgoSave(); sfx("kick");
      if (B.shells.length === 8 && bCos("oro")) { sfx("goal"); borgoToast("Tutte le conchiglie! Sbloccata la Maglia d'oro"); }
      else borgoToast(`Conchiglia! ${B.shells.length}/8`);
    });
    borgoPickupsX(tx, ty);
    if (B.q.glove === 1 && tx === GLOVE[0] && ty === GLOVE[1]) { B.q.glove = 2; borgoSave(); sfx("kick"); borgoToast("Trovato il guanto di Nico!"); }
  }

  // ---------- ingresso, uscita, comandi ----------
