      if (y > -10 && y < H + 10) for (let x = 1 * TS; x < 39 * TS; x += 8) { const sx = x - cx; if (sx < -8 || sx > W) continue; const c = ["#1e9e4a", "#f2f2f2", "#c8102e"][(x / 8) % 3]; g.fillStyle = c; g.beginPath(); g.moveTo(sx, y); g.lineTo(sx + 7, y); g.lineTo(sx + 3.5, y + 6 + Math.sin(frame / 12 + x) * 0.8); g.fill(); }
