      bSay([BL(id, line)], () => { borgoResume(); borgoToast(BW.bomb && !BW.bomb.left.length ? "Consegnate tutte! Corri da Sara" : `Consegnata! Ne mancano ${BW.bomb ? BW.bomb.left.length : 0}`); });
