    martello:   { label: "Martello", sub: "Fisico e rabbia · Contrasto +4, Dribbling −2", bias: { contr: 4, drib: -2 }, c1: "#3a1450", c2: "#ff7a45" },
    traversa:   { label: "Traversa e dentro", sub: "Prende il legno e rientra · Tiro +2, Passaggio +2, Dribbling −2", bias: { tiro: 2, pass: 2, drib: -2 }, c1: "#556b2f", c2: "#ffffff", cos: "traversa" },
    muro:       { label: "Rimbalzo del Muro", sub: "Equilibrio · tutte +1 (dal Borgo)", bias: { tiro: 1, drib: 1, pass: 1, contr: 1 }, c1: "#8e8a83", c2: "#ffd23f", cos: "muro" },
