  const heroDefault = () => ({ v: 1, name: "Luca", style: "spiky", hair: "#2b1d14", skin: "#f2c9a0", shirt: "#ff4d5a", acc: "none", num: 9, shot: "saetta", shotName: "SAETTA DI LUCA" });
