  function heroId() { return (M && M.hero) || (T && T.hero && view.kind !== "match") ? "hero" : "leo"; }
  function heroShot() {
    const h = M.hero, st = H_SHOTS[h.shot] || H_SHOTS.saetta;
    return { cost: 35, name: h.shotName || st.label.toUpperCase(), c1: st.c1, c2: st.c2, intro: `${h.name} prende la rincorsa…` };
  }
  function heroPower(st) {
    const k = (M.hero && M.hero.shot) || "saetta", dist = (5 - M.zone) * 5;
    if (k === "serpentina") return st.tiro * rnd(0.9, 1.2) + st.drib * 0.8 + 6 - dist * 0.6;
    if (k === "parabola") return st.tiro * rnd(0.95, 1.25) + st.pass * 0.7 + 6 - dist * 0.2;
    if (k === "martello") return st.tiro * rnd(0.9, 1.25) + st.contr * 0.9 + 6 - dist * 0.7;
    if (k === "traversa") return st.tiro * rnd(0.8, 1.35) + st.pass * 0.6 + 8 - dist * 0.5;
    if (k === "saudade") return st.tiro * rnd(0.9, 1.3) + (st.pass + st.drib) * 0.42 + 6 - dist * 0.3;
    if (k === "muro") return st.tiro * rnd(0.95, 1.2) + (st.drib + st.pass) * 0.38 + 6 - dist * 0.4;
    return st.tiro * rnd(0.9, 1.25) + st.tiro * 0.75 + 8 - dist;
  }
  // Applica il carattere del tiro alle statistiche (una volta sola)
  function heroBias(st, h) { const b = (H_SHOTS[h.shot] || H_SHOTS.saetta).bias; const o = { ...st }; Object.entries(b).forEach(([k, v]) => { o[k] = Math.max(4, (o[k] || 0) + v); }); return o; }
  const heroWhere = "Gioca al posto di Leo in Carriera, nel Torneo dei rigori e nelle partite del Borgo.";
