      buttons(opts.map(([a, right]) => ({ label: a, fn: () => { i++; if (right) ok++; view = { kind: "scene", bg: "borgo", speaker: "iole" }; text("iole", right ? pick(["Giusto.", "Bravo. Non te lo aspettavi nemmeno tu.", "Esatto. Vedi che a scuola ascoltavi?"]) : `No. La risposta era: <em>${esc(ans[0])}</em>.`); buttons([{ label: "Avanti ▸", fn: ask }]); } })));
