  function borgoMenu7(mark) {
    const q = B.q, out = [];
    if (npcHere("gino")) out.push(`${mark(q.post === 3)} La posta di Gino${q.post === 1 ? ` · ${3 - (q.postL || []).length}/3` : q.post === 2 ? " <span style='color:var(--dim)'>(torna da Gino)</span>" : ""}`);
    if (npcHere("iole")) out.push(`${mark(q.quiz)} L'interrogazione della maestra`);
    if (npcHere("bellandi")) out.push(`${mark(B.cos.includes("calzini"))} Il pescatore nuovo`);
    if (npcHere("duarte")) out.push(`${mark(q.pallDone)} Palleggi sulla sabbia · record <b>${q.pall || 0}</b>/15`);
    if (npcHere("nino")) out.push(`${mark(q.ninoDone)} Rigori al vecchio stadio · record <b>${q.nino || 0}</b>/5`);
    return out;
  }
  function borgoDecor7(cx, cy, n) {
    if (n < 6) return;
    // una carrozzina davanti a Casa Ferri
    const x = 8 * TS - cx + 4, y = 8 * TS - cy + 4;
    if (x > -20 && x < W + 20 && y > -20 && y < H + 20) { px(x, y, 12, 7, "#ff9ec0"); px(x - 2, y - 4, 7, 5, "#ff9ec0"); px(x + 11, y - 3, 1, 4, "#555"); g.fillStyle = "#333"; g.beginPath(); g.arc(x + 2, y + 8, 2, 0, 7); g.arc(x + 10, y + 8, 2, 0, 7); g.fill(); }
    // striscione del 6%
    const by = 12 * TS + 4 - cy, bx = 30 * TS - cx;
    if (bx > -60 && bx < W + 60 && by > -20 && by < H + 20) { px(bx - 30, by - 6, 60, 10, "#1b1b1b"); g.fillStyle = "#ffd23f"; g.font = "bold 7px sans-serif"; g.textAlign = "center"; g.fillText("IL CASO SIAMO NOI", bx, by + 1); g.textAlign = "left"; }
  }
  TRX.push(() => { const b = borgoLoad(), q = b.q, k = [q.post === 3, !!q.quiz, !!q.pallDone, !!q.ninoDone].filter(Boolean).length; return [{ name: "Amico del Borgo", kind: "heart", c: "#ff7a8a", got: k >= 4, part: `${k}/4`, hint: "Aiuta chi arriva in paese mentre la storia va avanti" }]; });

  // ================= STORIE EXTRA v7 =================
