    o.push(L("voce", ({ azzurro: "Stagione 3. La maglia azzurra, Fede finalmente leggero, Aldo Lanza portato via da due gendarmi.", ombre: "Stagione 3. Oro e ombre: una medaglia al collo, e Lanza ancora al suo posto a parlare di sanità pubblica.", argento: "Stagione 3. Argento vivo: il Brasile ha vinto, Jojo ti ha regalato la maglia. Due volte." })[f.end3] || "Stagione 3. La Nazionale."));
    o.push(L("voce", ({ pulito: "Stagione 4. Un fischio pulito: il Notaio ha firmato l'ultima cosa della sua carriera, cioè il verbale del suo arresto.", quinto: "Stagione 4. Il quinto uomo è rimasto nell'ombra, ma la Coppa Italia è sul bancone.", famiglia: "Stagione 4. Il derby di famiglia l'ha vinto Dario. Papà, in tribuna, ha pianto per tutti e due." })[f.end4] || "Stagione 4. La Serie A."));
    o.push(L("voce", ({ orecchie: "Stagione 5. Le grandi orecchie sull'altare di San Pietro, e un sì detto due volte, per sicurezza.", prezzo: "Stagione 5. La Champions pagata a un prezzo che solo tu conosci. E un matrimonio che nessuno ha potuto comprare.", si: "Stagione 5. La Champions a Parigi, il sì più bello a Borgo Marino. Nessuno si ricorda il risultato. Tutti si ricordano la torta." })[f.end5] || "Stagione 5. L'Europa."));
    o.push(L("voce", ({ sei: "Stagione 6. Il sei per cento aveva ragione. Tina è nata in un mondo un po' meno previsto.", previsto: "Stagione 6. Tutto previsto, tranne una bambina di tre chili e due etti che ha stretto il dito di Nico per trenta secondi.", culla: "Stagione 6. Una finale persa e una culla a Borgo Marino. Il campo comprato con le acciughe è ancora del paese." })[f.end6] || "Stagione 6. La Lega d'Oro."));
    o.push(L("voce", "Stagione 7. Il muro è di nuovo del Borgo. Sei nomi in una fotografia del 2006 sono diventati sei fascicoli. Li aveva visti per prima una donna che fotografava i gabbiani."));
    return o;
