    g.fillStyle = "rgba(255,190,110,0.16)"; g.fillRect(0, 0, pw, ph);
    const vg = g.createRadialGradient(pw / 2, ph / 2, ph * 0.35, pw / 2, ph / 2, pw * 0.72); vg.addColorStop(0, "rgba(0,0,0,0)"); vg.addColorStop(1, "rgba(40,20,0,0.55)"); g.fillStyle = vg; g.fillRect(0, 0, pw, ph);
    for (let i = 0; i < 90; i++) px((i * 97 + FOTOV.seed * 13) % pw, (i * 53 + FOTOV.seed * 7) % ph, 1, 1, i % 2 ? "#ffffff22" : "#00000022");
    g.fillStyle = "#ff9d2e"; g.font = "bold 8px monospace"; g.textAlign = "right"; g.fillText(FOTOV.stamp, pw - 4, ph - 4);
    g.restore();
    g.fillStyle = "#3a3a52"; g.font = "italic 10px Georgia, serif"; g.textAlign = "center"; g.fillText(f.t, 0, 86, 230); g.textAlign = "left";
