    if (state === "empty") { px(x, y, w, h, "#2a3448"); g.strokeStyle = "#56627a"; g.setLineDash([3, 3]); g.strokeRect(x + 2.5, y + 2.5, w - 5, h - 5); g.setLineDash([]); g.fillStyle = "#8a96ad"; g.font = "bold 10px sans-serif"; g.textAlign = "center"; g.fillText(String(figNum(id)), x + w / 2, y + h / 2 - 1); g.font = "6px sans-serif"; g.fillText(figName(id).slice(0, 18), x + w / 2, y + h / 2 + 9); g.textAlign = "left"; return; }
