  // ---------- statistiche ----------
  function tStat(id) {
    const c = TO_CH[id], d = tCh(id), s = { tiro: 0, drib: 0, pass: 0, contr: 0, par: 0, gr: 0, fat: 1, firma: 0 };
    Object.keys(c.base).forEach((k) => { s[k] += c.base[k] + (d.lv - 1) * (c.gr[k] || 0); });
    const add = (fx) => Object.entries(fx).forEach(([k, v]) => { if (k === "fat") s.fat *= v; else s[k] = (s[k] || 0) + v; });
    skTree(id).forEach((b) => { for (let i = 0; i < Math.min(3, d.sk[b.k] || 0); i++) add(b.nodes[i][1]); });
    const eq = TR().eq[id] || {}; Object.values(eq).forEach((it) => { if (TO_ITEMS[it]) add(TO_ITEMS[it].fx); });
    ["tiro", "drib", "pass", "contr", "par"].forEach((k) => { s[k] = Math.round(s[k]); });
    s.lv = d.lv; s.id = id; return s;
  }
