  const DUO = { doppia: "DOPPIA RONDINE", tuffo: "TUFFO DI TESTA", rovesciata: "ROVESCIATA", trio: "TIRO COMBINATO A TRE", gatto: "GATTO DI GUARDIA", muro: "MURO DI PUNTA NERA" };
