      const gr = g.createLinearGradient(0, 50, 0, 134); gr.addColorStop(0, "#1a0d05"); gr.addColorStop(1, c.c1); g.fillStyle = gr; g.fillRect(0, 50, W, 84);
      const s = 6 + k * 0.7; anPortrait(c.who, 160 - k * 6, 90 - 3 * s, s, false, c.c2);
      for (let i = 0; i < 18; i++) { const y = 52 + ((i * 13 + frame * 5) % 80); px(((i * 97 + frame * 22) % (W + 60)) - 60, y, 40, 1, "#ffffff66"); }
      if ((frame >> 2) % 3 === 0 && heavy) { g.save(); g.globalCompositeOperation = "lighter"; gxGlow(160 - 40, 88, 14, "255,255,255", 0.5); gxGlow(160 + 52, 88, 14, "255,255,255", 0.5); g.restore(); }
      g.restore();
