        g.globalAlpha = 1;
        if (c.cine === "rondine" || c.cine === "doppia") { const fl = Math.sin(frame / 2) * 5; anBird(bx + 2, by, 2.1, "#ff4d5acc", fl * 0.4); }
        if (c.cine === "foglia") { g.save(); g.translate(bx + 10, by - 8); g.rotate(frame / 5); g.fillStyle = "#7ee0a0"; g.fillRect(-4, -1.5, 8, 3); g.restore(); }
        ball(bx, by, 7);
