    for (let i = 0; i < 60; i++) px((i * 11 + (i % 3) * 3) % W, 14 + (i % 5) * 7, 4, 4, [C.T.c1, C.T.opp, "#e8e0d0", "#f0c9a0"][i % 4]);
    const gr = g.createLinearGradient(0, 60, 0, H); gr.addColorStop(0, "#2f9e55"); gr.addColorStop(1, "#15502a"); g.fillStyle = gr; g.fillRect(0, 60, W, H - 60);
    for (let i = 0; i < 5; i++) px(0, 150 + i * 12, W, 5, "rgba(255,255,255,.05)");
