    const off = (x, y) => { if (!amp) return [x, y]; const dx = x - ix, dy = y - iy, d2 = dx * dx + dy * dy; return [x + Math.sin(y / 7 + frame / 1.5) * amp * 0.4 * Math.exp(-d2 / 9000), y + Math.sin(x / 9 + frame / 1.2) * amp * Math.exp(-d2 / 9000)]; };
