    const who = us ? { hair: "#2a1a10", skin: "#e0b48a" } : gkN() === "Nico" ? "nico" : { hair: "#3a2a1a", skin: "#f0c9a0" };
    const kpos = (ss) => { const p = anEase((ss - 0.08) / (hitS - 0.08)), fall = clamp((ss - 0.62) / 0.2, 0, 1); return { x: 160 + dir * 34 * p + dir * 10 * fall, lift: dir ? Math.sin(Math.min(p, 1) * Math.PI / 2) * 34 * (1 - fall) : Math.sin(Math.min(p, 1) * Math.PI / 2) * 22 * (1 - fall), rot: dir * 1.35 * p + dir * 0.2 * fall, p }; };
