    gxFig(K.x, 142, KS, who, { ...kc, arms: "up", lift: K.lift, rot: K.rot, air: K.lift > 2, shout: hit });
    const glove = (Q) => ({ x: Q.x + Math.sin(Q.rot) * 24 * KS, y: 142 - Q.lift - Math.cos(Q.rot) * 24 * KS });
