    gxFig(ox, 164, S2, opp, { ...oc, ...oo, flip: oo.flip === undefined ? true : oo.flip });
    gxFig(lx, 164, S2, hero, lo);
    ball(bx, by, 5);
    if (slow) { g.fillStyle = "rgba(155,226,255,.08)"; g.fillRect(0, 0, W, H); g.font = "bold 11px sans-serif"; px(8, 12, 96, 16, "#000c"); g.fillStyle = "#ffd23f"; g.fillText("1 CONTRO 1", 14, 24); }
