  function encIsUnlocked(id) {
    if (id === "leo" || id === "papa" || id === "rita" || id === "ruggeri" || id === "nico" || id === "sara") return true;
    const cards = getList(CARDS);
    if (cards.includes(id)) return true;
    if (S && S.f && (S.f["met_" + id] || S.f["talk_" + id] || S.f[id])) return true;
    return false;
  }

  let curEncCat = "rondine";
  let curEncChar = "leo";

  function closeAltStage() {
    const alt = $("stageAlt");
    const cv = $("cv");
    if (alt) { alt.hidden = true; alt.innerHTML = ""; }
    if (cv) cv.hidden = false;
  }

  function render3DCard(charId, isUnlocked) {
    const alt = $("stageAlt");
    const cv = $("cv");
    if (!alt || !cv) return;
    cv.hidden = true;
    alt.hidden = false;

    const c = CAST[charId] || { name: charId };
    const ex = ENC_EXTRA[charId] || { role: "Figura del Borgo", quote: "«Sempre forza Rondine!»", stat: "Cuore ligure", bond: "Comunità" };
    const bio = BIO[charId] || "Abitante e figura chiave di Borgo Marino.";

    const name = isUnlocked ? (c.name || charId).toUpperCase() : "🔒 ??? SCONOSCIUTO";
    const role = isUnlocked ? ex.role : "Mistero del Borgo";
    const quote = isUnlocked ? ex.quote : "«Incrocia questo personaggio nel Borgo o nella storia per sbloccare la sua carta.»";
    const statName = isUnlocked ? ex.stat : "???";

    const avatarEmoji = isUnlocked ? (
      charId === "leo" ? "🦅" :
      charId === "nico" ? "🧤" :
      charId === "sara" ? "📋" :
      charId === "tommy" ? "⚡" :
      charId === "gigi" ? "🕊️" :
      charId === "nonna" ? "🚗" :
      charId === "baciccia" ? "🐟" :
      charId === "ester" ? "🗼" :
      charId === "tonino" ? "🍨" :
      charId === "pietrino" ? "⚽" : "⭐"
    ) : "🔒";

    alt.innerHTML = `
      <div class="holo-card-wrap" id="holoCardWrap" title="Tocca per girare la carta · Muovi per inclinare in 3D">
        <div class="holo-card" id="holoCard">
          <div class="holo-side holo-front">
            <div class="holo-sheen" id="holoSheen"></div>
            <div class="holo-header">
              <span>${esc(name)}</span>
              <span class="holo-role">${esc(role)}</span>
            </div>
            <div class="holo-body">
              <div class="holo-avatar-frame">
                <span>${avatarEmoji}</span>
              </div>
              <div class="holo-stats">
                <div class="holo-stat-row">
                  <span>Specialità:</span>
                  <b style="color:#57d68d; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:68px;">${esc(statName)}</b>
                </div>
                <div class="holo-stat-row">
                  <span>Potenza</span>
                  <div class="holo-stat-bar"><div class="holo-stat-fill" style="width:${isUnlocked ? '85%' : '15%'};"></div></div>
                </div>
                <div class="holo-stat-row">
                  <span>Rarità</span>
                  <span style="color:#ffd23f;">${isUnlocked ? '★★★★★' : '★☆☆☆☆'}</span>
                </div>
              </div>
            </div>
            <div class="holo-footer">
              ${esc(quote)}
            </div>
          </div>

          <div class="holo-side holo-back">
            <div class="holo-back-emblem">🦅</div>
            <div class="holo-back-title">ALI DI RONDINE · CARD #${charId.toUpperCase()}</div>
            <div class="holo-back-desc">
              ${isUnlocked ? esc(bio) : "<i>Questa carta è ancora sigillata nel mazzo. Esplora Borgo Marino o avanza nei capitoli per sbloccarla.</i>"}
            </div>
            <div class="holo-flip-hint">Tocca per girare di nuovo 🔄</div>
          </div>
        </div>
      </div>
    `;

    const wrap = document.getElementById("holoCardWrap");
    const card = document.getElementById("holoCard");
    const sheen = document.getElementById("holoSheen");

    if (wrap && card) {
      const handleMove = (clientX, clientY) => {
        const rect = wrap.getBoundingClientRect();
        const x = clientX - rect.left;
        const y = clientY - rect.top;
        const midX = rect.width / 2;
        const midY = rect.height / 2;
        const rotY = ((x - midX) / midX) * 20;
        const rotX = -((y - midY) / midY) * 20;

        if (!card.classList.contains("flipped")) {
          card.style.transform = `rotateX(${rotX}deg) rotateY(${rotY}deg)`;
          if (sheen) sheen.style.backgroundPosition = `${x * 1.5}px ${y * 1.5}px`;
        }
      };

      wrap.onmousemove = (e) => handleMove(e.clientX, e.clientY);
      wrap.ontouchmove = (e) => {
        if (e.touches && e.touches[0]) handleMove(e.touches[0].clientX, e.touches[0].clientY);
      };
      wrap.onmouseleave = () => {
        if (!card.classList.contains("flipped")) card.style.transform = "rotateX(0deg) rotateY(0deg)";
      };
      wrap.onclick = () => {
        card.classList.toggle("flipped");
        try { playCarHorn(); } catch {}
      };
    }
  }

  function borgoEncyclopedia(backFn, catId, charId) {
    if (backFn) borgoEncyclopedia._back = backFn;
    const bFn = borgoEncyclopedia._back || title;
    if (catId) curEncCat = catId;
    const cat = ENC_CATS.find(c => c.id === curEncCat) || ENC_CATS[0];
    if (charId && cat.members.includes(charId)) curEncChar = charId;
    else if (!cat.members.includes(curEncChar)) curEncChar = cat.members[0];

    view = { kind: "enciclopedia", bg: "title", charId: curEncChar };
    chap("Enciclopedia del Borgo");
    statsBox();

    // Calcolo progresso sblocco totale
    let totalEnc = 0, unlockedEnc = 0;
    ENC_CATS.forEach(ct => {
      ct.members.forEach(m => {
        totalEnc++;
        if (encIsUnlocked(m)) unlockedEnc++;
      });
    });

    const isUnlocked = encIsUnlocked(curEncChar);
    const c = CAST[curEncChar] || { name: curEncChar };
    const bioText = BIO[curEncChar] || "Abitante e figura chiave delle vicende di Borgo Marino.";
    const ex = ENC_EXTRA[curEncChar] || { role: "Figura del Borgo", quote: "«Sempre forza Rondine!»", stat: "Cuore ligure", bond: "Comunità" };

    if (SET.cardView !== "canvas") {
      render3DCard(curEncChar, isUnlocked);
    } else {
      closeAltStage();
    }

    if (isUnlocked) {
      text("voce", `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
          <div>
            <span class="who gold" style="font-weight:bold; font-size:13px; color:#0e1424;">${esc(c.name || curEncChar)}</span>
            <span style="font-size:12px; color:var(--dim); margin-left:6px;">${esc(ex.role)}</span>
          </div>
          <span style="font-size:11px; color:#ffd23f; font-weight:bold;">Scoperti ${unlockedEnc}/${totalEnc}</span>
        </div>
        <div style="font-style:italic; color:#ffd23f; margin:4px 0 8px; font-size:13px; border-left:3px solid #ffd23f; padding-left:8px;">
          ${esc(ex.quote)}
        </div>
        <div style="font-size:13.5px; line-height:1.45; color:var(--ink); margin-bottom:8px;">
          ${esc(bioText)}
        </div>
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px; font-size:11.5px; background:rgba(0,0,0,0.25); border-radius:6px; padding:6px 8px;">
          <div><b>Specialità:</b> <span style="color:#57d68d;">${esc(ex.stat)}</span></div>
          <div><b>Legame:</b> <span style="color:#3fa7ff;">${esc(ex.bond)}</span></div>
        </div>
      `);
    } else {
      text("voce", `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
          <div>
            <span class="who" style="background:#475569; color:#fff; font-weight:bold; font-size:12px; padding:2px 8px; border-radius:4px;">🔒 Personaggio non ancora incontrato</span>
            <span style="font-size:12px; color:var(--dim); margin-left:6px;">Mistero del Borgo</span>
          </div>
          <span style="font-size:11px; color:#ffd23f; font-weight:bold;">Scoperti ${unlockedEnc}/${totalEnc}</span>
        </div>
        <div style="font-style:italic; color:#94a3b8; margin:4px 0 8px; font-size:13px; border-left:3px solid #64748b; padding-left:8px;">
          «??? Non hai ancora incrociato questa persona nella storia o nel Borgo.»
        </div>
        <div style="font-size:13px; line-height:1.45; color:var(--ink); margin-bottom:8px; background:rgba(0,0,0,0.25); border-radius:6px; padding:8px 10px; border:1px dashed rgba(255,255,255,0.15);">
          <b style="color:#ffd23f;">Come sbloccarlo:</b> ${esc(ENC_HINTS[curEncChar] || "Incontralo proseguendo nei capitoli della storia o visitando i luoghi del paese.")}
        </div>
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px; font-size:11.5px; background:rgba(0,0,0,0.25); border-radius:6px; padding:6px 8px;">
          <div><b>Specialità:</b> <span style="color:var(--dim);">🔒 Da scoprire</span></div>
          <div><b>Legame:</b> <span style="color:var(--dim);">🔒 Ignoto</span></div>
        </div>
      `);
    }

    const catBtns = ENC_CATS.map(ct => ({
      label: ct.name,
      cls: ct.id === curEncCat ? "hot" : "",
      fn: () => borgoEncyclopedia(bFn, ct.id, ct.members[0])
    }));

    const memberBtns = cat.members.map(mId => {
      const ok = encIsUnlocked(mId);
      const mc = CAST[mId] || { name: mId };
      const isCur = mId === curEncChar;
      const label = ok ? ((isCur ? "★ " : "") + (mc.name || mId)) : (isCur ? "★ 🔒 ???" : "🔒 ???");
      return {
        label: label,
        cls: isCur ? "hot" : (ok ? "" : "dim"),
        fn: () => borgoEncyclopedia(bFn, curEncCat, mId)
      };
    });

    const toggleStyleBtn = {
      label: SET.cardView === "canvas" ? "✨ Passa a Carta Olografica 3D" : "🖼️ Torna a Pixel Canvas",
      sub: SET.cardView === "canvas" ? "Attiva la carta tridimensionale con riflessi Foil" : "Disattiva la carta 3D e torna al canvas classico",
      cls: "pick",
      fn: () => {
        SET.cardView = SET.cardView === "canvas" ? "holo3d" : "canvas";
        writeJSON(SETK, SET);
        borgoEncyclopedia(bFn, curEncCat, curEncChar);
      }
    };

    buttons([
      ...memberBtns,
      { label: "── Stile di Visualizzazione ──", disabled: true },
      toggleStyleBtn,
      { label: "── Scegli Categoria ──", disabled: true },
      ...catBtns,
      { label: "◂ Torna indietro", cls: "pick", fn: () => { closeAltStage(); bFn(); } }
    ]);
  }

