  const MN_COLL = [];
  function menuImp() {
    view = { kind: "scene", bg: "stadium" }; chap("Impostazioni");
    const gr = guRec(), gd = Object.keys(MANUALE_CHAPTERS).filter((k) => gr.done && gr.done[k]).length;
    text("voce", `<b>Impostazioni</b><br>Difficoltà ${(DIFF[SET.diff] || DIFF.normale)[0]} · Animazioni ${SET.anim ? "sì" : "no"} · Grafica ${{ classica: "classica", migliorata: "migliorata", pixel: "pixel art rifinita" }[SET.gfx] || "migliorata"}<br><span style="color:var(--dim)">Tutto si salva da solo. Da «Salvataggi» puoi portare i progressi su un altro telefono.</span>`);
    buttons([
      { label: "Impostazioni", sub: "Difficoltà, stile partite, animazioni, suoni, testo", cls: "hot", fn: () => settings(menuImp) },
      { label: "Salvataggi", sub: "Esporta · Importa", fn: saves },
      { label: "📖 Manuale del Rondine FC", sub: `Capitoli consultati ${gd}/${Object.keys(MANUALE_CHAPTERS).length} · Guide complete`, cls: "hot", fn: () => manualeRondine(menuImp) },
      { label: "Dove andare adesso?", sub: "Un consiglio senza spoiler", fn: () => guDove(menuImp) },
      { label: "◂ Menu", fn: title },
    ], true);
  }

  // ---------- «Dove andare adesso?»: Pina consiglia, senza rovinare niente ----------
  const GU_TIPS = []; // consigli aggiunti dagli item successivi: () => ({ t, b }) | null
  function guTips() {
    const out = [], has = load(), sd = (k) => seasonDone(k);
    if (has && STORY[has.step]) out.push({ t: `La storia ti aspetta dove l'hai lasciata: «${esc(STORY[has.step].chap)}».`, b: { label: "Continua la storia", cls: "hot", fn: () => { S = has; run(); } } });
    else {
      const k = SEASONS.find((n) => !sd(n) && (n < 8 || sd(7)) && (n < 9 || sd(8)));
      const pk = { 2: pickS2, 3: pickS3, 4: pickS4, 5: pickS5, 6: pickS6, 7: pickS7, 8: pickS8, 9: pickS9 };
      if (k === 1) out.push({ t: "Si comincia dall'inizio: la Stagione 1 dura mezz'oretta e ti presenta tutti. Anche quelli che parlano troppo.", b: { label: "Nuova partita", cls: "hot", fn: () => { S = fresh(); run(); } } });
      else if (k) out.push({ t: `La Stagione ${k} è ancora da giocare. Il pullman non aspetta, ma la storia sì.`, b: { label: `Stagione ${k}`, cls: "hot", fn: pk[k] } });
    }
    try { const dt = dailyToday(), r = dayRec(); if (r.last !== dt.key) out.push({ t: `La sfida del giorno è ancora lì: «${esc(dt.title)}». Domani ce n'è un'altra, ma questa è di oggi.`, b: { label: "Sfida del giorno", fn: daily } }); } catch {}
    try { if (!B) B = borgoLoad(); const f = bFest(); if (f) out.push({ t: `Oggi al Borgo c'è ${esc(FEST[f].name)}: ${esc(FEST[f].actName.toLowerCase())}, con premio in monete.`, b: { label: "Vai al Borgo", fn: borgo } }); } catch {}
    try { const b = B || borgoLoad(); if (b.shells.length < 8) out.push({ t: `Sulla spiaggia mancano ${8 - b.shells.length} conchiglie. Io non dico dove, ma una volta ne ho trovata una dentro una scarpa.`, b: { label: "Vai al Borgo", fn: borgo } }); } catch {}
    GU_TIPS.forEach((f) => { try { const x = f(); if (x) out.push(x); } catch {} });
    try { if (legOpen() && !(dfRec().wins.leggenda > 0)) out.push({ t: "Hai sbloccato la difficoltà Leggenda. Lì perdere è normale: vincere è una storia da raccontare in edicola.", b: { label: "Impostazioni", fn: () => settings(menuImp) } }); } catch {}
    try {
      const t = trophies().find((x) => !x.got && x.part && x.hint && !/\?\?\?/.test(x.hint) && !/\?\?\?/.test(x.name));
      if (t) out.push({ t: `Un trofeo alla portata: <b>${esc(t.name)}</b> (${esc(String(t.part))}). ${esc(t.hint)}.`, b: { label: "Bacheca dei trofei", fn: () => bacheca(title) } });
    } catch {}
    if (!guRec().seen) out.push({ t: "Se è la prima volta, c'è una guida rapida: due minuti, niente compiti a casa.", b: { label: "Guida rapida", fn: () => guida(title) } });
    out.push({ t: "Non sai cosa c'è in giro? Sulla mappa delle modalità c'è tutto quello che hai aperto, e qualche punto di domanda.", b: { label: "Mappa delle modalità", fn: () => mappa(title) } });
    return out;
  }
  function guDove(back) {
    back = back || title;
    const gr = guRec(), all = guTips(), off = (gr.tips || 0) % Math.max(1, all.length - 1);
    const pickT = [all[0], ...all.slice(1).slice(off), ...all.slice(1).slice(0, off)].slice(0, 3);
    view = { kind: "scene", bg: "borgo", speaker: "pina" }; chap("Dove andare adesso?");
    text("pina", `Allora, ascoltami bene, che io in edicola sento tutto:<br>${pickT.map((x) => `• ${x.t}`).join("<br>")}`);
    buttons([
      ...pickT.map((x) => ({ ...x.b })),
      ...(all.length > 3 ? [{ label: "Altri consigli", sub: "Pina ne sa sempre una più del giornale", fn: () => { const r = guRec(); r.tips = (r.tips || 0) + 2; guSave(r); guDove(back); } }] : []),
      { label: "◂ Indietro", fn: back },
    ]);
  }

