  function drawMappa() {
    // mare, carta, isole
    const sea = g.createLinearGradient(0, 0, 0, H); sea.addColorStop(0, "#0e3a5c"); sea.addColorStop(1, "#092a44"); g.fillStyle = sea; g.fillRect(0, 0, W, H);
    for (let i = 0; i < 18; i++) { const y = (i * 23) % H, x = ((i * 67 + frame * 0.3) % (W + 40)) - 20; px(x, y, 10, 1, "rgba(160,210,255,.25)"); }
    const land = (x, y, w, h, c) => { g.fillStyle = c; g.beginPath(); g.ellipse(x, y, w, h, 0, 0, 7); g.fill(); };
    land(56, 100, 58, 92, "#e9d9a8"); land(186, 104, 82, 90, "#dfe8c4"); land(288, 100, 32, 92, "#e6d3b0");
    g.font = "bold 7px sans-serif"; g.textAlign = "center"; g.fillStyle = "rgba(60,40,20,.55)";
    g.fillText("IL BORGO", 56, 16); g.fillText("LO STADIO", 186, 16); g.fillText("IL FARO", 288, 16);
    // sentieri
    const byId = (id) => MAPN.find((n) => n.id === id);
    MAPN.forEach((n) => { const f = n.from ? byId(n.from) : null; if (!f || f === n) return; g.strokeStyle = n.ok() ? "rgba(179,32,44,.55)" : "rgba(80,80,80,.35)"; g.lineWidth = 1.5; g.setLineDash(n.ok() ? [] : [3, 3]); g.beginPath(); g.moveTo(f.x, f.y); g.quadraticCurveTo((f.x + n.x) / 2, Math.min(f.y, n.y) - 12, n.x, n.y); g.stroke(); g.setLineDash([]); });
    // luoghi
    MAPN.forEach((n, i) => {
      const ok = n.ok(), sel = MAPV && MAPV.sel === i, r = sel ? 9 : 7;
      if (sel) { g.strokeStyle = "#ffd23f"; g.lineWidth = 2; g.beginPath(); g.arc(n.x, n.y, r + 4 + Math.sin(frame / 8), 0, 7); g.stroke(); }
      g.fillStyle = ok ? (sel ? "#ff4d5a" : "#b3202c") : "#7a7a7a"; g.beginPath(); g.arc(n.x, n.y, r, 0, 7); g.fill();
      g.fillStyle = "#fff"; g.font = "bold 8px sans-serif"; g.fillText(ok ? "★" : "?", n.x, n.y + 3);
      const lbl = ok ? n.t : "???"; g.font = `bold ${sel ? 8 : 7}px sans-serif`; const w = g.measureText(lbl).width + 6;
      px(n.x - w / 2, n.y + r + 1, w, 10, ok ? "rgba(255,255,255,.85)" : "rgba(40,40,40,.6)"); g.fillStyle = ok ? "#2a1a10" : "#ddd"; g.fillText(lbl, n.x, n.y + r + 9);
    });
    g.textAlign = "left";
    // rosa dei venti
    g.fillStyle = "rgba(255,255,255,.5)"; g.font = "bold 8px sans-serif"; g.fillText("N", 306, 190); g.strokeStyle = "rgba(255,255,255,.5)"; g.beginPath(); g.moveTo(308, 182); g.lineTo(308, 170); g.stroke();
  }
