  function clubRecord(tab, a, b, ga, gb) { const A = tab[a], B0 = tab[b]; A.g++; B0.g++; A.gf += ga; A.gs += gb; B0.gf += gb; B0.gs += ga; if (ga > gb) { A.v++; B0.p++; A.pt += 3; } else if (ga < gb) { B0.v++; A.p++; B0.pt += 3; } else { A.n++; B0.n++; A.pt++; B0.pt++; } }
  const clubStand = (tab, ids) => ids.map((id) => ({ id, ...tab[id] })).sort((a, b) => b.pt - a.pt || (b.gf - b.gs) - (a.gf - a.gs) || b.gf - a.gf || (a.id === "lanterna" ? -1 : b.id === "lanterna" ? 1 : clubRating(b.id) - clubRating(a.id)));
