    try { gxGlow(70, 96, 60, "255,220,160", 0.45); } catch {}
    g.fillStyle = "#ffe0a0"; g.beginPath(); g.arc(70, 96, 14, 0, 7); g.fill();
    px(0, 96, W, 22, "#3a5a8a"); for (let i = 0; i < 9; i++) px((i * 43 + frame * 0.2) % W, 100 + (i % 3) * 5, 10, 1, "#ffd8a066");
