    for (let i = 0; i < 5; i++) { g.fillStyle = i % 2 ? "#3a8236" : "#44913f"; g.fillRect(i * 64, 128, 64, 72); }
    g.strokeStyle = "#ffffffaa"; g.lineWidth = 1; g.beginPath(); g.moveTo(8, 130); g.lineTo(312, 124); g.stroke(); g.beginPath(); g.moveTo(160, 127); g.lineTo(160, 200); g.stroke();
    g.beginPath(); g.ellipse(160, 160, 24, 9, 0, 0, 7); g.stroke();
