      pal: { f1: "#8a8578", f2: "#908b7e", ln: "#6c685d", r1: "#4a4a52", r2: "#505058", sd: "#d9c9a0", sea: "#3d6f8f", hi: "#b8d8e8", g1: "#4f9a52", g2: "#55a058", w1: "#8e8a83", w2: "#aaa59c", leaf: "#3f7d3a", fruit: "", sc: "#d9a520", st: "TRAM", m1: "#d9a520", m2: "#f2f2f2", k1: "#7a746a", k2: "#9a948a", b: "#5a4a3a" },
