    text("voce", `${esc(c.p)}<br>Cosa gli dici prima del fischio?`);
    buttons(c.a.map(([q, conf, rep]) => ({ label: q, fn: () => { view = { kind: "scene", bg: "beach", speaker: c.who }; text(c.who, esc(rep)); buttons([{ label: "Fischio d'inizio ▸", cls: "hot", fn: () => a1Play(T, conf, 0, [0, 0], [], back) }]); } })));
