    if (id === "bemulini" && !beNight()) { const k = frame / 60, x = 8 * TS - cx + Math.sin(k) * 30, y = 7 * TS - cy - 20 + Math.cos(k * 1.3) * 10; if (on(x, y)) { g.strokeStyle = "#ffffffaa"; g.beginPath(); g.moveTo(8 * TS - cx + 8, 11 * TS - cy); g.lineTo(x, y); g.stroke(); g.fillStyle = "#ff4d5a"; g.beginPath(); g.moveTo(x, y - 7); g.lineTo(x + 7, y); g.lineTo(x, y + 5); g.lineTo(x - 7, y); g.fill(); } }
