    if (z.dark) { g.fillStyle = "rgba(10,40,90,.28)"; g.fillRect(0, 0, W, H); g.save(); g.globalCompositeOperation = "lighter"; for (let i = 0; i < 18; i++) { const x = ((i * 53 + Math.sin(frame / 30 + i) * 20) % W + W) % W, y = ((i * 31 + Math.cos(frame / 40 + i) * 12) % H + H) % H; px(x, y, 2, 2, "rgba(150,230,255,.5)"); } g.restore(); return; }
