      if (id === "bebagni") { const x = 15 * TS - cx + 8, y = 13 * TS - cy + 4; const gr = g.createRadialGradient(x, y, 2, x, y, 50); gr.addColorStop(0, "rgba(255,150,60,.55)"); gr.addColorStop(1, "rgba(0,0,0,0)"); g.fillStyle = gr; g.fillRect(x - 60, y - 60, 120, 120); }
