  const czCard = (r, id) => { const lv = Math.max(1, Math.min(CZ_MAXLV, r.lv[id] || 1)), rr = czRarOf(id); return { id, name: CAST[id].name, role: czRoleOf(id), rar: rr, lv, dup: czDupHave(r, id), pw: CZ_RR[rr][1] + (lv - 1) * 1.5 }; };
  const czAll = (r) => czIds().map((id) => czCard(r, id));
  const czTeamIds = (r) => ["p", "d", "c", "a"].flatMap((g) => r.team[g]).filter(Boolean);
  const czStars = (n) => "★".repeat(n) + "☆".repeat(CZ_MAXLV - n);
