            if (window.S && window.S.st) window.S.st.grinta = Math.min(100, (window.S.st.grinta || 80) + 15);
            sfx("goal");
            borgoToast("+15 Grinta recuperata! Piatto spazzolato.");
            text("papa", "«Così si fa! Piatto pulito e sguardo dritto verso la prossima partita!»");
